package com.portfolio.features.experience.service; import com.portfolio.common.exception.NotFoundException; import com.portfolio.features.experience.dto.*; import com.portfolio.features.experience.entity.Experience; import com.portfolio.features.experience.repository.ExperienceRepository; import com.portfolio.features.portfolio.entity.Portfolio; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class ExperienceService {private final ExperienceRepository repo;private final PortfolioAccessService access;@Transactional(readOnly=true) public List<Experience> list(AppUser u){return repo.findByPortfolioIdOrderBySortOrderAscStartDateDesc(access.mine(u).getId());}@Transactional public Experience create(AppUser u,ExperienceRequest r){Experience e=new Experience();e.setPortfolio(access.mine(u));apply(e,r);return repo.save(e);}@Transactional public Experience update(AppUser u,UUID id,ExperienceRequest r){Experience e=owned(u,id);apply(e,r);return e;}@Transactional public void delete(AppUser u,UUID id){repo.delete(owned(u,id));}private Experience owned(AppUser u,UUID id){Experience e=repo.findById(id).orElseThrow(()->new NotFoundException("Experience not found."));access.owned(u,e.getPortfolio().getId());return e;}private void apply(Experience e,ExperienceRequest r){e.setCompany(r.company().trim());e.setPosition(r.position().trim());e.setLocation(r.location());e.setStartDate(r.startDate());e.setEndDate(r.endDate());e.setCurrentlyWorking(r.currentlyWorking());e.setDescription(r.description());e.setSortOrder(r.sortOrder());}}
